namespace App\Entity;

use Doctrine\Common\Collections\ArrayCollection;
use Doctrine\ORM\Mapping as ORM;
use Gedmo\Mapping\Annotation as Gedmo;
use Symfony\Component\HttpFoundation\File\File;
use Symfony\Component\Validator\Constraints as Assert;
use Vich\UploaderBundle\Mapping\Annotation as Vich;

#[ORM\Table(name: 'universe_lives')]
#[ORM\Entity(repositoryClass: \App\Repository\LiveRepository::class)]
#[Assert\Callback(['App\Validation\Validator', 'validate'])]
#[Gedmo\SoftDeleteable(fieldName: 'deletedAt', timeAware: false, hardDelete: true)]
#[Vich\Uploadable]
class Live
{
    /**
     * NOTE: This is not a mapped field of entity metadata, just a simple property.
     *
     * @var File
     */
    #[Assert\File(maxSize: '32M', mimeTypes: ['image/jpeg', 'image/jpg', 'image/gif', 'image/png'], mimeTypesMessage: 'The file should be an image')]
    #[Vich\UploadableField(mapping: 'live_main_image', fileNameProperty: 'mainImage', size: 'imageSize', mimeType: 'imageMimeType', originalName: 'imageOriginalName', dimensions: 'imageDimensions')]
    private $mainImageFile;
    #[ORM\Column(type: 'string', length: 255, nullable: true)]
    private $mainImage;

    // Getters and setters...
    #[ORM\Id]
    #[ORM\Column(type: 'integer')]
    #[ORM\GeneratedValue(strategy: 'AUTO')]
    private $id;
    #[ORM\Column(length: 255, unique: true)]
    #[Gedmo\Slug(fields: ['title'], updatable: true)]
    private $slug;

    #[ORM\Column(type: 'boolean')]
    private $hidden;
    #[ORM\Column(type: 'string', length: 50, nullable: true)]
    #[Assert\NotBlank]
    private $title;

    #[ORM\Column(type: 'string', length: 50, nullable: true)]
    #[Assert\NotBlank]
    private $link;
    #[ORM\Column(type: 'text', nullable: true)]
    #[Assert\NotBlank]
    private $description;
    #[Gedmo\Timestampable(on: 'create')]
    #[ORM\Column(type: 'datetime')]
    private $createdAt;
    #[ORM\Column(type: 'string', length: 255, nullable: true)]
    private $imageName;
    /**
     *
     * @var integer
     */
    #[ORM\Column(type: 'integer', nullable: true)]
    private $imageSize;

    /**
     *
     * @var integer
     */
    #[ORM\Column(type: 'integer', nullable: true)]
    private $status;
    #[ORM\Column(type: 'string', length: 255, nullable: true)]
    private $imageMimeType;
    #[ORM\Column(type: 'string', length: 255, nullable: true)]
    private $imageOriginalName;
    #[ORM\Column(type: 'simple_array', nullable: true)]
    private $imageDimensions;
    #[Gedmo\Timestampable(on: 'create')]
    #[ORM\Column(type: 'datetime')]
    private $updatedAt;
    #[ORM\Column(type: 'datetime', nullable: true)]
    private $deletedAt;

    public function __construct()
    {
    }

    /**
     * @return string
     */
    public function getStatusStringified(): string
    {
        $status = $this->getStatus();

        if ($status == 1) {
            return "Standby";
        }
        if ($status == 2) {
            return "Live";
        }

        return "";
    }

    /**
     * @return int
     */
    public function getStatus(): int
    {
        return $this->status;
    }

    /**
     * @param int $status
     */
    public function setStatus(int $status): void
    {
        $this->status = $status;
    }

    /**
     * @return mixed
     */
    public function getLink()
    {
        return $this->link;
    }

    /**
     * @param mixed $link
     */
    public function setLink($link): void
    {
        $this->link = $link;
    }

    /**
     * @return mixed
     */
    public function getImageName()
    {
        return $this->imageName;
    }

    /**
     * @param mixed $imageName
     */
    public function setImageName($imageName): void
    {
        $this->imageName = $imageName;
    }

    /**
     * @return int
     */
    public function getImageSize()
    {
        return $this->imageSize;
    }

    /**
     * @param int $imageSize
     */
    public function setImageSize(int $imageSize): void
    {
        $this->imageSize = $imageSize;
    }

    /**
     * @return mixed
     */
    public function getImageMimeType()
    {
        return $this->imageMimeType;
    }

    /**
     * @param mixed $imageMimeType
     */
    public function setImageMimeType($imageMimeType): void
    {
        $this->imageMimeType = $imageMimeType;
    }

    /**
     * @return mixed
     */
    public function getImageOriginalName()
    {
        return $this->imageOriginalName;
    }

    /**
     * @param mixed $imageOriginalName
     */
    public function setImageOriginalName($imageOriginalName): void
    {
        $this->imageOriginalName = $imageOriginalName;
    }

    /**
     * @return mixed
     */
    public function getImageDimensions()
    {
        return $this->imageDimensions;
    }

    /**
     * @param mixed $imageDimensions
     */
    public function setImageDimensions($imageDimensions): void
    {
        $this->imageDimensions = $imageDimensions;
    }

    public function getImagePath()
    {
        return $this->mainImage ? 'uploads/lives/' . $this->mainImage : null;
    }

    /**
     * Get the count of associated events
     */
    public function getEventsCount(): int
    {
        return $this->events->count();
    }

    public function getEvents()
    {
        return $this->events;
    }

    /**
     * Get the count of associated event dates
     */
    public function getEventDatesCount()
    {
        $eventDatesCount = 0;

        foreach ($this->events as $event) {
            $eventDatesCount += $event->getEventDates()->count();
        }

        return $eventDatesCount;
    }

    public function addEvent($event)
    {
        $this->events->add($event);
        $event->setVenue($this);
    }

    public function removeEvent($event)
    {
        $this->events->removeElement($event);
        $event->setVenue(null);
    }

    /**
     * @return mixed
     */
    public function getMainImageFile()
    {
        return $this->mainImageFile;
    }

    /**
     * @param mixed $mainImageFile
     */
    public function setMainImageFile($mainImageFile): void
    {
        $this->mainImageFile = $mainImageFile;
    }

    /**
     * @return mixed
     */
    public function getMainImage()
    {
        return $this->mainImage;
    }

    /**
     * @param mixed $mainImage
     */
    public function setMainImage($mainImage): void
    {
        $this->mainImage = $mainImage;
    }

    public function getImagePlaceholder($size = "default")
    {
//        if ($size == "small") {
//            return "data:image/png;base64,";
//        }
//        return "data:image/png;base64,";
        return '/uploads/imgs/default.jpg';
    }

    /**
     * @return mixed
     */
    public function getSlug()
    {
        return $this->slug;
    }

    /**
     * @param mixed $slug
     */
    public function setSlug($slug): void
    {
        $this->slug = $slug;
    }

    /**
     * @return mixed
     */
    public function getId()
    {
        return $this->id;
    }

    /**
     * @param mixed $id
     */
    public function setId($id): void
    {
        $this->id = $id;
    }

    /**
     * @return mixed
     */
    public function getAvailability()
    {
        return $this->availability;
    }

    /**
     * @param mixed $availability
     */
    public function setAvailability($availability): void
    {
        $this->availability = $availability;
    }

    /**
     * @return mixed
     */
    public function getHidden()
    {
        return $this->hidden;
    }

    /**
     * @param mixed $hidden
     */
    public function setHidden($hidden): void
    {
        $this->hidden = $hidden;
    }

    /**
     * @return mixed
     */
    public function getTitle()
    {
        return $this->title;
    }

    /**
     * @param mixed $title
     */
    public function setTitle($title): void
    {
        $this->title = $title;
    }

    /**
     * @return mixed
     */
    public function getDescription()
    {
        return $this->description;
    }

    /**
     * @param mixed $description
     */
    public function setDescription($description): void
    {
        $this->description = $description;
    }

    /**
     * @return mixed
     */
    public function getContactEmail()
    {
        return $this->contactEmail;
    }

    /**
     * @param mixed $contactEmail
     */
    public function setContactEmail($contactEmail): void
    {
        $this->contactEmail = $contactEmail;
    }

    /**
     * @return mixed
     */
    public function getCreatedAt()
    {
        return $this->createdAt;
    }

    /**
     * @param mixed $createdAt
     */
    public function setCreatedAt($createdAt): void
    {
        $this->createdAt = $createdAt;
    }

    /**
     * @return mixed
     */
    public function getUpdatedAt()
    {
        return $this->updatedAt;
    }

    /**
     * @param mixed $updatedAt
     */
    public function setUpdatedAt($updatedAt): void
    {
        $this->updatedAt = $updatedAt;
    }

    /**
     * @return mixed
     */
    public function getDeletedAt()
    {
        return $this->deletedAt;
    }

    /**
     * @param mixed $deletedAt
     */
    public function setDeletedAt($deletedAt): void
    {
        $this->deletedAt = $deletedAt;
    }

    /**
     * @return ArrayCollection
     */
    public function getSecondaryImages()
    {
        return $this->secondaryImages;
    }

    public function addSecondaryImage(VenueImage $image)
    {
        $this->secondaryImages->add($image);
        $image->setVenue($this);
    }

    public function removeSecondaryImage(VenueImage $image)
    {
        $this->secondaryImages->removeElement($image);
    }
}
